changeSet.sql:
ALTER TABLE public.tenant_organization
    ADD COLUMN IF NOT EXISTS retailer_size_band_code character varying(64);
INSERT INTO public.retailer_size_band (retailer_type_code, code, label, min_locations, max_locations, sort_order, is_active)
SELECT 'GAS_STATION', 'SINGLE', 'Single site', 1, 4, 1, true
WHERE NOT EXISTS (SELECT 1 FROM public.retailer_size_band WHERE retailer_type_code = 'GAS_STATION' AND code = 'SINGLE');
INSERT INTO public.retailer_size_band (retailer_type_code, code, label, min_locations, max_locations, sort_order, is_active)
SELECT 'GAS_STATION', 'MID', 'Mid size', 5, 10, 2, true
WHERE NOT EXISTS (SELECT 1 FROM public.retailer_size_band WHERE retailer_type_code = 'GAS_STATION' AND code = 'MID');
INSERT INTO public.retailer_size_band (retailer_type_code, code, label, min_locations, max_locations, sort_order, is_active)
SELECT 'GAS_STATION', 'ENTERPRISE', 'Enterprise', 11, NULL, 3, true
WHERE NOT EXISTS (SELECT 1 FROM public.retailer_size_band WHERE retailer_type_code = 'GAS_STATION' AND code = 'ENTERPRISE');
INSERT INTO public.retailer_size_band (retailer_type_code, code, label, min_locations, max_locations, sort_order, is_active)
SELECT code, 'STANDARD', 'Standard', 1, NULL, 1, true
FROM public.retailer_type
WHERE tenant_id IS NULL
  AND code IN ('LIQUOR_STORE', 'DUNKIN_DONUTS', 'SEVEN_ELEVEN', 'RESTAURANT', 'CLINIC')
  AND NOT EXISTS (
      SELECT 1 FROM public.retailer_size_band band
      WHERE band.retailer_type_code = retailer_type.code AND band.code = 'STANDARD'
  );

UPDATE public.tenant_organization
   SET retailer_type_code = 'GAS_STATION'
 WHERE retailer_type_code = 'GAS_STATION_ENT';
UPDATE public.retail_location
   SET retailer_type_code = 'GAS_STATION'
 WHERE retailer_type_code = 'GAS_STATION_ENT';
UPDATE public.retailer_type
   SET is_active = false,
       hint = 'Retired. Size is a retailer_size_band on GAS_STATION.'
 WHERE tenant_id IS NULL AND code = 'GAS_STATION_ENT';

ALTER TABLE public.retail_recommendation DROP CONSTRAINT IF EXISTS chk_retail_recommendation__category;
ALTER TABLE public.platform_billing_plan DROP CONSTRAINT IF EXISTS chk_platform_billing_plan__product;
ALTER TABLE public.platform_billing_plan
    ADD CONSTRAINT chk_platform_billing_plan__product CHECK (product IN ('EVENT_SITE', 'GAS_STATION', 'RETAIL'));
ALTER TABLE public.tenant_product_billing DROP CONSTRAINT IF EXISTS chk_tenant_product_billing__product;
ALTER TABLE public.tenant_product_billing
    ADD CONSTRAINT chk_tenant_product_billing__product CHECK (product IN ('EVENT_SITE', 'GAS_STATION', 'RETAIL'));
INSERT INTO public.platform_billing_plan (product, name, code, billing_mode, billing_interval, list_price_usd, published, feature_summary, graduated_tiers_json)
SELECT 'RETAIL', 'Gas station single', 'GAS_STATION_SINGLE', 'RECURRING', 'MONTH', 0, false, 'Placeholder. Price follows the gas pack and the SINGLE size band.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.platform_billing_plan WHERE product = 'RETAIL' AND code = 'GAS_STATION_SINGLE');
INSERT INTO public.platform_billing_plan (product, name, code, billing_mode, billing_interval, list_price_usd, published, feature_summary, graduated_tiers_json)
SELECT 'RETAIL', 'Gas station mid', 'GAS_STATION_MID', 'RECURRING', 'MONTH', 0, false, 'Placeholder. Price follows the gas pack and the MID size band (5 to 10 locations).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.platform_billing_plan WHERE product = 'RETAIL' AND code = 'GAS_STATION_MID');
INSERT INTO public.platform_billing_plan (product, name, code, billing_mode, billing_interval, list_price_usd, published, feature_summary, graduated_tiers_json)
SELECT 'RETAIL', 'Gas station enterprise', 'GAS_STATION_ENTERPRISE', 'RECURRING', 'MONTH', 0, false, 'Placeholder. Price follows the gas pack and the ENTERPRISE size band.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.platform_billing_plan WHERE product = 'RETAIL' AND code = 'GAS_STATION_ENTERPRISE');
